--
-- Table structure for table `announcements`
--

DROP TABLE IF EXISTS `announcements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `announcements` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci,
  `announcement_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `publish_date` date DEFAULT NULL,
  `inspection_start_date` date DEFAULT NULL,
  `inspection_end_date` date DEFAULT NULL,
  `inspection_unit` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_count` int DEFAULT '0',
  `attachment_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attachment_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cosmetics',
  `announcement_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sampling',
  `source_detail_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_page` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_json_file` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `announcement_level` varchar(24) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `announcement_level_label` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sampling_unqualified_batch_count` int DEFAULT NULL COMMENT '抽检不合格批次数',
  `sampling_qualified_batch_count` int DEFAULT NULL,
  `sampling_total_batch_count` int DEFAULT NULL COMMENT '抽检样品总批次数',
  `status` enum('draft','published','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `author_id` int DEFAULT NULL,
  `view_count` int DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `author_id` (`author_id`),
  KEY `idx_announcements_product_type` (`product_type`),
  KEY `idx_announcements_announcement_type` (`announcement_type`),
  KEY `idx_announcements_source_detail_url` (`source_detail_url`(191)),
  CONSTRAINT `announcements_ibfk_1` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

