CREATE TABLE `food_inspection_products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `food_inspection_id` int NOT NULL,
  `attachment_id` int DEFAULT NULL,
  `sequence_no` int NOT NULL DEFAULT '1',
  `product_name` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `company_names` text COLLATE utf8mb4_unicode_ci,
  `company_addresses` text COLLATE utf8mb4_unicode_ci,
  `manufacturer_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufacturer_address` text COLLATE utf8mb4_unicode_ci,
  `operator_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator_address` text COLLATE utf8mb4_unicode_ci,
  `sample_unit_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sample_unit_address` text COLLATE utf8mb4_unicode_ci,
  `package_spec` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `batch_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `production_date` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expiry_date` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_region` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_institution` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unqualified_items` longtext COLLATE utf8mb4_unicode_ci,
  `inspection_result` longtext COLLATE utf8mb4_unicode_ci,
  `requirement` longtext COLLATE utf8mb4_unicode_ci,
  `remarks` longtext COLLATE utf8mb4_unicode_ci,
  `raw_payload` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `attachment_id` (`attachment_id`),
  KEY `idx_food_product_notice` (`food_inspection_id`),
  KEY `idx_food_product_name` (`product_name`),
  KEY `idx_food_product_company` (`company_names`(191)),
  KEY `idx_food_product_issue` (`unqualified_items`(191)),
  CONSTRAINT `food_inspection_products_ibfk_1` FOREIGN KEY (`food_inspection_id`) REFERENCES `food_inspection` (`id`) ON DELETE CASCADE,
  CONSTRAINT `food_inspection_products_ibfk_2` FOREIGN KEY (`attachment_id`) REFERENCES `food_inspection_attachments` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
