DROP TABLE IF EXISTS `inspection_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inspection_details` (
  `id` int NOT NULL AUTO_INCREMENT,
  `inspection_id` int NOT NULL,
  `product_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `brand` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` int DEFAULT NULL,
  `manufacturer` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `production_date` date DEFAULT NULL,
  `sample_source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inspection_result` enum('qualified','unqualified','pending') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `unqualified_items` text COLLATE utf8mb4_unicode_ci,
  `inspection_standard` longtext COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `inspection_id` (`inspection_id`),
  KEY `idx_inspection_details_company_id` (`company_id`),
  KEY `idx_inspection_details_company_result` (`company_id`,`inspection_result`),
  CONSTRAINT `inspection_details_ibfk_1` FOREIGN KEY (`inspection_id`) REFERENCES `inspections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `inspection_details_ibfk_2` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4335 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
