CREATE TABLE `unqualified_product_issue_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `unqualified_product_id` int NOT NULL,
  `announcement_id` int DEFAULT NULL,
  `announcement_detail_id` int DEFAULT NULL,
  `issue_item` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_unqualified_product_issue_item` (`unqualified_product_id`,`issue_item`),
  KEY `idx_upii_issue_item` (`issue_item`),
  KEY `idx_upii_product` (`unqualified_product_id`),
  KEY `idx_upii_announcement` (`announcement_id`),
  KEY `idx_upii_announcement_detail` (`announcement_detail_id`),
  KEY `idx_upii_issue_item_announcement` (`issue_item`,`announcement_id`),
  CONSTRAINT `fk_upii_unqualified_product` FOREIGN KEY (`unqualified_product_id`) REFERENCES `unqualified_products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6317 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
