--
-- Table structure for table `unqualified_products`
--

DROP TABLE IF EXISTS `unqualified_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `unqualified_products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `batch_title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_batches` int DEFAULT '0',
  `sequence_no` int NOT NULL COMMENT '序号',
  `product_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称',
  `company_names` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '注册人/备案人、受托生产企业、境内责任人（经销商）等名称',
  `company_addresses` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '注册人/备案人、受托生产企业、境内责任人（经销商）等地址',
  `manufacturer_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufacturer_address` text COLLATE utf8mb4_unicode_ci,
  `operator_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operator_address` text COLLATE utf8mb4_unicode_ci,
  `sample_unit_name` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '被抽样单位名称',
  `sample_unit_address` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '被抽样单位地址',
  `package_spec` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '包装规格',
  `batch_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标示批号',
  `production_date` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标示生产日期',
  `expiry_date` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标示限期使用日期/保质期',
  `product_region` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标示化妆品注册人/备案人、受托生产企业、境内责任人（经销商）所在地/产品进口地区',
  `registration_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '特殊化妆品注册证编号/普通化妆品备案编号',
  `production_license_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标示生产许可证号',
  `inspection_institution` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验机构名称',
  `unqualified_items` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '不符合规定项目',
  `inspection_result` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验结果',
  `requirement` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规定要求',
  `remarks` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `picture_url` varchar(768) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufacturer_province` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `manufacturer_city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sampled_province` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sampled_city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issue_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cosmetics',
  `announcement_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sampling',
  `source_key` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_title` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_publish_date` datetime DEFAULT NULL,
  `source_year` int DEFAULT NULL,
  `province_display` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_id` int DEFAULT NULL,
  `announcement_id` int DEFAULT NULL,
  `announcement_detail_id` int DEFAULT NULL,
  `supervision_id` int DEFAULT NULL,
  `supervision_detail_id` int DEFAULT NULL,
  `is_counterfeit` tinyint DEFAULT '0' COMMENT '是否假冒产品',
  `usage_user` json DEFAULT NULL COMMENT '使用用户（保存文案时追加 JSON 记录：username/display_name/saved_at）',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `pictture_url` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `food_body_text` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '食品官方正文',
  PRIMARY KEY (`id`),
  KEY `idx_sequence_no` (`sequence_no`),
  KEY `idx_product_name` (`product_name`),
  KEY `idx_company_names` (`company_names`(255)),
  KEY `idx_sample_unit_name` (`sample_unit_name`(255)),
  KEY `idx_unqualified_products_sample_unit_name` (`sample_unit_name`),
  KEY `idx_unqualified_products_inspection_institution` (`inspection_institution`),
  KEY `idx_unqualified_products_announcement` (`announcement_id`),
  KEY `idx_unqualified_products_counterfeit` (`is_counterfeit`),
  KEY `idx_unqualified_products_announcement_detail` (`announcement_detail_id`),
  KEY `idx_unqualified_products_list_order` (`announcement_id`,`sequence_no`,`id`),
  KEY `idx_unqualified_products_product_region` (`product_region`),
  KEY `idx_unqualified_products_product_category` (`product_category`),
  KEY `idx_unqualified_products_manufacturer_province` (`manufacturer_province`),
  KEY `idx_unqualified_products_sampled_province` (`sampled_province`),
  KEY `idx_unqualified_products_issue_category` (`issue_category`),
  KEY `idx_unqualified_products_supervision` (`supervision_id`),
  KEY `idx_unqualified_products_supervision_detail` (`supervision_detail_id`),
  KEY `idx_unqualified_products_product_type` (`product_type`),
  KEY `idx_unqualified_products_announcement_type` (`announcement_type`),
  KEY `idx_unqualified_products_source_key` (`source_key`),
  KEY `idx_unqualified_products_source_year` (`source_year`),
  KEY `idx_unqualified_products_source_publish_date` (`source_publish_date`),
  KEY `idx_unqualified_products_province_display` (`province_display`),
  KEY `idx_unqualified_products_company_id` (`company_id`),
  KEY `idx_unqualified_products_tree_filters` (`source_year`,`announcement_type`,`product_type`),
  KEY `idx_unqualified_products_province_year` (`province_display`,`source_year`),
  KEY `idx_unqualified_products_source_order` (`source_publish_date`,`id`),
  KEY `idx_unqualified_products_manufacturer_name` (`manufacturer_name`),
  KEY `idx_unqualified_products_operator_name` (`operator_name`),
  KEY `idx_unqualified_products_manufacturer_city` (`manufacturer_city`),
  KEY `idx_unqualified_products_sampled_city` (`sampled_city`),
  CONSTRAINT `fk_unqualified_products_announcement` FOREIGN KEY (`announcement_id`) REFERENCES `announcements` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_unqualified_products_announcement_detail` FOREIGN KEY (`announcement_detail_id`) REFERENCES `announcement_product_details` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_unqualified_products_company` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_unqualified_products_supervision` FOREIGN KEY (`supervision_id`) REFERENCES `supervisions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_unqualified_products_supervision_detail` FOREIGN KEY (`supervision_detail_id`) REFERENCES `flight_inspection_detail` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5061 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='不符合规定化妆品信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

